   ```rust
   fn describe(result: &ProbeResult) -> String {
       match result {
           ProbeResult::Ok { latency } => format!("{}ms", latency.0),
           ProbeResult::Timeout { budget } => format!("no answer in {}ms", budget.0),
           ProbeResult::HttpError { status } => format!("HTTP {status}"),
