       let fixture = vec![
           ProbeResult::Ok { latency: LatencyMs(212) },
           ProbeResult::Ok { latency: LatencyMs(487) },
           ProbeResult::Timeout { budget: LatencyMs(3000) },
           ProbeResult::HttpError { status: 429 },
           ProbeResult::Ok { latency: LatencyMs(1204) },
